# find shapes: regions separated by row of 5s
def shapes(g):
    sep=[r for r,row in enumerate(g) if all(x==5 for x in row)]
    sh=[]
    seen=set()
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] not in (0,5) and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; cells=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b))
                    if 0<=a<len(g) and 0<=b<len(g[0]) and g[a][b]==col:
                        cells.append((a,b))
                        stack += [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                cells=[x for x in cells if g[x[0]][x[1]]==col]
                rs=[x[0] for x in cells]; cs=[x[1] for x in cells]
                bbox=[[g[i][j] if g[i][j]==col else 0 for j in range(min(cs),max(cs)+1)] for i in range(min(rs),max(rs)+1)]
                sh.append({'col':col,'r0':min(rs),'c0':min(cs),'bbox':bbox,'cells':len(cells)})
    return sh
